using Essco.Domain.Liquidations;
namespace Essco.Application.Liquidations;

public interface ILiquidationExpenseRepository { ValueTask<IReadOnlyCollection<LiquidationExpense>> ListAsync(LiquidationExpenseFilter f, CancellationToken t); ValueTask<int> CreateAsync(LiquidationExpense x, CancellationToken t); ValueTask<bool> UpdateAsync(LiquidationExpense x, CancellationToken t); ValueTask<bool> AnnulAsync(int id, CancellationToken t); ValueTask<bool> LinkAsync(int id, int? liquidation, string type, CancellationToken t); }
public sealed class LiquidationExpenseService(ILiquidationExpenseRepository repository)
{ public ValueTask<IReadOnlyCollection<LiquidationExpense>> ListAsync(LiquidationExpenseFilter f, CancellationToken t) => repository.ListAsync(f, t); public async ValueTask<(bool Succeeded, int Id, IReadOnlyCollection<string> Errors)> SaveAsync(LiquidationExpense x, bool isNew, CancellationToken t) { x = x with { LiquidationType = x.LiquidationType.Trim().ToUpperInvariant() }; var e = x.Validate(); if (e.Count > 0) return (false, x.Id, e); var ok = isNew ? (await repository.CreateAsync(x, t)) : (await repository.UpdateAsync(x, t) ? x.Id : 0); return ok > 0 ? (true, ok, []) : (false, x.Id, ["El gasto ya no existe o está anulado."]); } public ValueTask<bool> AnnulAsync(int id, CancellationToken t) => repository.AnnulAsync(id, t); public ValueTask<bool> LinkAsync(int id, int? n, string type, CancellationToken t) => repository.LinkAsync(id, n, type.Trim().ToUpperInvariant(), t); }
